	RANK_RULES_VISIBILITY = "Qui peut le voir",
	RANK_RULE_ARENA_EVIDENCE = "Le classement est reconstruit à partir des registres de combats classés conservés. Un registre manquant ou rejeté ne crée pas de résultat.",
	RANK_RULE_ARENA_LIMITS = "Un combat classé demande au moins %d secondes par manche en moyenne. Au plus %d combats par joueur et par jour serveur, et %d combats contre le même adversaire en %d jours, comptent. Les répétitions et les combats non confirmés ne comptent pas.",
	RANK_RULE_ARENA_ORDER = "Les rangs de tous les temps se basent sur la cote la plus haute, puis le plus de combats classés, puis le nom ; des cotes égales partagent une place. Les vues par période utilisent la cote gagnée, les victoires, le moins de défaites, la cote actuelle, puis le nom.",
	RANK_RULE_ARENA_REPEAT = "Les combats répétés entre la même paire en moins de %d heures comptent progressivement pour 1, 1/2, 1/4 et ainsi de suite.",
	RANK_RULE_ARENA_SCORE = "Un combattant sans cote reportée commence à %d. Entre les saisons, une cote conservée revient à mi-chemin vers %d. K=%d ne s'applique que tant que le combattant n'est pas établi et a moins de %d combats classés ; un combattant établi peut donc commencer en dehors de %d et utilise K=%d, ou K=%d à partir de la cote %d. Chaque niveau d'écart compte pour %d points de cote ; l'écart total de score attendu est plafonné à %d.",
	RANK_RULE_ARENA_TITLE = "Cote d'arène",
	RANK_RULE_ARENA_VISIBILITY = "L'équipe des jeux le voit toujours. Les membres ne le voient que tant que l'interrupteur Arène d'un éditeur autorisé est ouvert.",
	RANK_RULE_BONES_EVIDENCE = "Seules comptent les moitiés de partie signées concordantes conservées par ce client. Les moitiés manquantes restent inconnues.",
	RANK_RULE_BONES_LIMITS = "Une partie demande au moins %d secondes. Au plus %d parties par joueur et par jour serveur, et %d parties contre le même adversaire en %d jours, comptent.",
	RANK_RULE_BONES_ORDER = "Le plus de victoires passe en premier ; en cas d'égalité, le moins de parties, puis le moment le plus tôt où ce total de victoires a été atteint, puis le nom. Le champion et le podium du mois précédent clos sont conservés à part.",
	RANK_RULE_BONES_SCORE = "Le mois civil en cours classe les victoires confirmées entre joueurs. L'entraînement, les parties contre la maison, les rerolls d'un même propriétaire, les joueurs masqués et les registres dont les deux moitiés signées ne concordent pas ne comptent pas.",
	RANK_RULE_BONES_TITLE = "Classement du Lancer d'os",
	RANK_RULE_BONES_VISIBILITY = "L'équipe des jeux le voit toujours. Les membres ne le voient que tant que l'interrupteur Lancer d'os d'un éditeur autorisé est ouvert.",
	RANK_RULE_CHURCH_EVIDENCE = "Seuls comptent les registres de recrues confirmées et de maintien ultérieur détenus par les livres de l'Église. Les registres manquants sont inconnus et ne créent pas de points.",
	RANK_RULE_CHURCH_FULLNESS_ORDER = "Le plus de jours qualifiants complets passe en premier. En cas d'égalité, la moyenne la plus haute des moyennes journalières qualifiantes, puis le nom de la guilde.",
	RANK_RULE_CHURCH_FULLNESS_TITLE = "Classement du remplissage des guildes",
	RANK_RULE_CHURCH_FULLNESS_VISIBILITY = "C'est réservé au public de l'Église ; cela ne fait pas partie du classement public de l'Église.",
	RANK_RULE_CHURCH_ORDER = "Le score total le plus haut passe en premier ; en cas d'égalité, les points propres les plus hauts, puis le nom. Les fenêtres semaine, 30 jours et depuis toujours ne comptent que les preuves datées dans cette fenêtre.",
	RANK_RULE_CHURCH_SCORE = "Une recrue confirmée rapporte %d points. Une recrue toujours dans Olympus après %d jours en rapporte %d de plus. Un responsable reçoit aussi %d%%, %d%% et %d%% des points propres gagnés aux trois premiers niveaux sous lui ; les parts ne se cumulent pas.",
	RANK_RULE_CHURCH_TITLE = "Classement du service de l'Église",
	RANK_RULE_CHURCH_VISIBILITY = "Le public de l'Église voit le classement complet. La page publique ne montre que les lignes des volontaires tant que l'interrupteur de publication autorisé est ouvert.",
	RANK_RULE_CRAFT_EVIDENCE = "Le demandeur et l'artisan signent la même commande terminée. En cas de désaccord, la rareté observée la plus basse est retenue ; une revendication unilatérale n'entre jamais dans le classement.",
	RANK_RULE_CRAFT_LIMITS = "Au plus %d livraisons entre le même demandeur et le même artisan comptent par jour, et aucun joueur ne peut ajouter plus de %d registres d'artisanat en une journée.",
	RANK_RULE_CRAFT_ORDER = "Le plus de points passe en premier, puis le plus de clients différents, puis le plus de livraisons, puis le nom du personnage.",
	RANK_RULE_CRAFT_SCORE = "Une livraison confirmée commence à 10 points. Les quantités plus grandes ajoutent un bonus borné et sous-linéaire ; les productions peu communes, rares, épiques et légendaires ajoutent des points de rareté croissants. Connaître une recette ne donne à elle seule aucun point.",
	RANK_RULE_CRAFT_TITLE = "Classement du service d'artisanat",
	RANK_RULE_CRAFT_VISIBILITY = "Le registre signé est conservé et relayé par les clients qui le détiennent, donc le classement mondial mensuel n'exige pas que l'un ou l'autre des joueurs d'origine reste en ligne.",
	RANK_RULE_DEBTORS_EVIDENCE = "Seules comptent les entrées confirmées du registre des frais détenues par le bureau des frais ou sa dernière réponse privée. Les entrées non confirmées attendent hors du classement.",
	RANK_RULE_DEBTORS_ORDER = "Le plus de cuivre en retard passe en premier, puis le plus de cuivre dû au total, puis le nom. Le palier de recouvrement change à l'échéance, après %d heures et après %d heures.",
	RANK_RULE_DEBTORS_SCORE = "Ce n'est pas un classement d'honneur. Des frais de guilde confirmés sont dus %d heures après la vente directe conclue. Les frais ouverts sont regroupés par artisan, avec le total dû et les montants déjà en retard gardés à part.",
	RANK_RULE_DEBTORS_TITLE = "Ordre de recouvrement des frais d'artisanat",
	RANK_RULE_DEBTORS_VISIBILITY = "Seuls les lecteurs privés existants du registre des frais peuvent le voir. Rien ici ne publie de dette ni ne déplace d'or automatiquement.",
	RANK_RULE_DONORS_DUES = "Quand le livre du Trésorier est partagé hors de sa vue privée, la part possible de cotisations hebdomadaires est retirée. Les livres des autres gardiens montrent les dons qualifiants tels qu'enregistrés.",
	RANK_RULE_DONORS_EVIDENCE = "Ce client classe les livres qu'il détient actuellement. Un livre manquant ou plus ancien est une preuve manquante ou plus ancienne, pas zéro.",
	RANK_RULE_DONORS_ORDER = "Le plus de cuivre qualifiant passe en premier ; les totaux égaux sont classés par nom.",
	RANK_RULE_DONORS_SCORE = "Les dons entrants qualifiants sont additionnés en cuivre. Les lignes du registre renvoyées, sortantes, transférées et exclues ne s'ajoutent pas au total.",
	RANK_RULE_DONORS_TITLE = "Classement des donateurs",
	RANK_RULE_DONORS_VISIBILITY = "Le Roi, ses Intendants et les gardiens peuvent le voir. Les autres membres ne le voient que tant que l'interrupteur de classement du Roi est ouvert.",
	RANK_RULE_GUILD_TREASURY_EVIDENCE = "Chaque ligne utilise le dernier instantané autorisé détenu ici. Des prix d'objets en attente font de son total un montant « au moins ». Les guildes manquantes et les objets sans prix restent inconnus.",
	RANK_RULE_GUILD_TREASURY_ORDER = "Le total le plus haut passe en premier ; en cas d'égalité, le niveau moyen connu le plus haut, puis le nom de la guilde. Le Trésor fédéral est affiché à part et ne prend pas de place.",
	RANK_RULE_GUILD_TREASURY_SCORE = "Le total de chaque guilde est l'or de son instantané de banque autorisé plus la valeur connue configurée ou de vente au marchand de chaque objet. La valeur des objets sans prix n'est pas inventée.",
	RANK_RULE_GUILD_TREASURY_TITLE = "Classement des trésors de guilde",
	RANK_RULE_GUILD_TREASURY_VISIBILITY = "Seul le public privé existant des trésors de guilde peut voir ce classement. Il n'est pas publié à l'armée.",
	RANK_RULE_LEVEL_EVIDENCE = "Seules les listes des meilleurs personnages des rapports de guilde récents détenus par ce client sont incluses. C'est une vue locale du recensement, pas une certification du serveur.",
	RANK_RULE_LEVEL_ORDER = "Le niveau le plus haut passe en premier ; les niveaux égaux sont classés par nom de personnage. La page affiche au plus %d personnages, %d à la fois.",
	RANK_RULE_LEVEL_SCORE = "Il n'y a pas de points : les personnages sont classés selon leur dernier niveau rapporté.",
	RANK_RULE_LEVEL_TITLE = "Course aux niveaux",
	RANK_RULE_LEVEL_VISIBILITY = "Chaque membre d'Olympus peut voir la même page de classement, construite à partir des rapports que son client a entendus.",
	RANK_RULE_WANTED_BOUNTY = "Pour les preuves actuelles avec score, une mort comptée ajoute à la prime ouverte du joueur de la Horde le niveau de la victime et le bonus de sa plus haute charge vérifiée : Roi 100, Haut Conseil 50, maître de guilde 30, Légat 20, autre charge 10, membre 0, jusqu'à un plafond de prime ouverte de %d. Une répétition actuelle avec score dans les %d minutes n'ajoute ni prime ni autre victime comptée. Les anciennes preuves de compatibilité sans champs de score gardent leur ancien comportement : elles ajoutent une victime historique et jusqu'à 1 point de prime sous le même plafond ; la protection actuelle contre les répétitions avec score ne s'applique pas.",
	RANK_RULE_WANTED_EVIDENCE = "Les tableaux locaux utilisent les lignes conservées par ce client et les lignes vérifiées que les membres d'Olympus lui ont partagées ; ce ne sont pas des totaux certifiés par le serveur. Les preuves manquantes restent inconnues. Les anciens scores ne sont recalculés que là où les faits conservés prouvent le résultat ; sinon, l'ancien total reste archivé au lieu d'être deviné dans le classement.",
	RANK_RULE_WANTED_LIMITS = "Pour les preuves actuelles avec score, la base de niveau compte au plus une fois pour le même tueur et la même cible en %d minutes, et la vengeance au plus une fois en %d heures. Les morts et les victimes en instance ne comptent pas. Les entrées de la Horde sans prime et sans victime restent hors de la liste visible des Recherchés.",
	RANK_RULE_WANTED_ORDER = "Les Recherchés sont classés par prime ouverte actuelle la plus haute, puis le plus de victimes comptées au total, puis le nom. Les Chasseurs du mois et de tous les temps sont classés par le plus de points, puis le moment le plus tôt où ce total a été atteint, puis une identité stable. Seul un top trois mondial signé contrôle les cadres de Chasseur.",
	RANK_RULE_WANTED_SLAYER = "Une victime de la Horde actuelle avec score et qualifiante rapporte un point de base par tranche de %d niveaux de la Horde, arrondi au supérieur, plus toute la prime ouverte et %d points pour une vengeance admissible. La vengeance doit répondre à la propre mort de ce joueur dans les %d jours. Une ancienne revendication de compatibilité sans champs de score ne paie que la prime ouverte, sans base de niveau ni vengeance.",
	RANK_RULE_WANTED_TITLE = "Classements des Recherchés et des Chasseurs",
	RANK_RULE_WANTED_VISIBILITY = "Les membres d'Olympus peuvent lire ces règles et les registres que leur propre client détient. Seuls le Roi, le Haut Conseil signé et l'auteur peuvent publier le top trois mondial signé. Les lignes de position et les marqueurs de carte obéissent aussi aux contrôles distincts du partage de position et de la modération.",
	RB_APOSTLE_1 = "Salut,\n\nTu es maintenant l'un des Douze Apôtres de l'Église missionnaire d'Olympus. Douze. Pas un de plus. C'est énorme.\n\nLe boulot : amener de nouveaux joueurs dans Olympus, et bâtir un réseau de missionnaires qui font pareil.\n\nCe qui se voit : les trois meilleurs Apôtres des 30 derniers jours portent la croix des Apôtres, et tout le monde la voit.",
	RB_APOSTLE_2 = "Ce que tu obtiens :\n- Jusqu'à 12 missionnaires à toi (onglet Église, Nommer, ou clic droit sur un joueur).\n- L'onglet Église : le classement, tes chiffres, les gens.\n- Le salon des Apôtres et les salons de l'Église dans l'onglet Discussion.\n- Pendant que tu joues, ton addon tient le registre de l'Église pour tout le monde.\n\nUne règle : nomme des gens qui vont vraiment le faire.",
	RB_APOSTLE_LAUNCH = "Bon, écoute.\n\nLe jeu est lancé. Tu es l'un des douze Apôtres de toute l'armée. C'est énorme. Maintenant, l'Église doit mériter son nom.\n\nMême boulot : amener de nouveaux joueurs dans Olympus, et former des missionnaires qui font pareil.\n\n- Nomme des missionnaires : jusqu'à 12 chacun, dans l'onglet Église (Nommer) ou par clic droit sur un joueur. Ils nomment les leurs, jusqu'à cinq niveaux sous toi. 5 000 dans toute l'Église, maximum.\n- Points : 10 pour chaque joueur nouveau dans Olympus qui arrive par toi, 5 de plus s'il est encore là 7 jours plus tard. Plus 25 %, 10 % ainsi que 5 % obtenus sur ce que rapportent tes trois niveaux en dessous. Quelqu'un en dessous de toi peut te dépasser. Tant mieux. Ça veut dire que ça marche.\n- Tu as amené quelqu'un qu'un autre joueur a invité ? Enregistre-le : il compte s'il rejoint une guilde Olympus sous 14 jours.\n- Les trois meilleurs Apôtres des 30 derniers jours portent la croix.\n- Quelqu'un a arrêté de jouer ? Retire-le. Les gens qu'il a nommés gardent leur place.\n\nUne règle : uniquement de vrais nouveaux joueurs. Les rerolls et les changements de guilde au sein d'Olympus ne comptent jamais. Les points, c'est seulement dans le jeu, jamais de l'or.\n\nLaisse ton addon activé quand tu joues. Il tient le registre de l'Église. C'est parti !",
	RB_APOSTLE_LAUNCH_TITLE = "L'Église, au lancement",
	RB_APOSTLE_RED = "Dans Mon profil, sous Apparence, il y a aussi une croix rouge que toi seul vois.",
	RB_APOSTLE_TITLE = "Apôtre",
	RB_BACK = "< Toutes les lettres de fonction",
	RB_BTN_CHURCH = "Église",
	RB_BTN_CRAFTERS = "Artisans",
	RB_BTN_DECREES = "Décrets",
	RB_BTN_GUILD = "Onglet Guilde",
	RB_BTN_THRONE = "Le Trône",
	RB_BTN_TREASURY = "Trésor",
	RB_BTN_WAR = "Salle de guerre",
	RB_BTN_WATCH = "La Garde",
	RB_CHURCHCORR = "Salut,\n\nTu es maintenant le correspondant de l'Église de <%s>. Tu réponds au Chef de l'Église. C'est-à-dire moi.\n\nLe boulot : garder ta guilde pleine.\n\nCe qui se voit : pas de nouveau cadre.\n\nCe que tu obtiens :\n- L'onglet Église : le classement, tes propres chiffres, et les gens.\n- Enregistrer une recrue que tu as amenée, jusqu'à 15 en cours à la fois. Elle compte pour toi si elle rejoint une guilde Olympus sous 14 jours et qu'elle est nouvelle dans Olympus.\n- Le salon de l'Église dans l'onglet Discussion.\n\nTon classement, c'est le nombre de jours d'affilée au-dessus de 950 membres, compté depuis ta nomination.\n\nUne règle : fais grandir ta guilde, mais jamais en débauchant des gens d'une autre guilde Olympus.",
	RB_CHURCHCORR_TITLE = "Correspondant de l'Église",
	RB_CHURCH_LETTER_LINK = "Ta lettre du Roi",
	RB_CHURCH_LETTER_TIP = "La lettre de ta fonction : le boulot, ce qui se voit et ce que ça débloque.",
	RB_CORR_ARTISANRY = "Salut,\n\nTu es maintenant le correspondant de l'Artisanat de <%s>. Le meilleur ami des artisans.\n\nLe boulot : aider tes camarades de guilde à trouver des artisans, et faire arriver les demandes, les matériaux et les fournitures à ceux qui en ont besoin.\n\nCe qui se voit : le bouclier de l'Association de l'Artisanat sur ton portrait et à côté de ton nom.\n\nCe que tu obtiens :\n- Le tableau des Artisans, à un clic de ton onglet Guilde.\n- Le salon de l'Association de l'Artisanat, et le salon Maître et Correspondants.\n\nLes outils propres au département ne sont pas encore là. Pour l'instant, c'est toi qu'on vient voir.\n\nUne règle : personne dans ta guilde ne reste coincé sans son craft.",
	RB_CORR_ARTISANRY_TITLE = "Correspondant de l'Artisanat",
	RB_CORR_CHURCHDEPT = "Salut,\n\nTu es maintenant le correspondant de <%s> pour l'Église missionnaire.\n\nLe boulot : amener de nouveaux joueurs, et aider à garder ta guilde pleine.\n\nCe qui se voit : le bouclier de l'Église missionnaire sur ton portrait et à côté de ton nom.\n\nCe que tu obtiens : le titre, et le salon du département. Honnêtement, c'est tout. Ça montre à tout le monde qui est le contact Église de ta guilde.\n\nPour le salon de l'Église elle-même et les chiffres de recrutement, il te faut aussi une place dans l'Église. Ton maître de guilde nomme le correspondant de l'Église dans l'onglet Église, ou un Apôtre te nomme missionnaire.\n\nUne règle : amène de vrais nouveaux joueurs. Les rerolls et les changements de guilde au sein d'Olympus ne comptent jamais.",
	RB_CORR_CHURCHDEPT_TITLE = "Correspondant de l'Église missionnaire",
	RB_CORR_HERALDRY = "Bon,\n\nTu es maintenant le correspondant de l'Héraldique de <%s>. Tu es la voix de ta guilde.\n\nLe boulot : gérer les décrets, l'Agenda et les rassemblements de ta guilde, et faire venir les gens aux événements et aux streams.\n\nCe qui se voit : le bouclier du Département de l'Héraldique sur ton portrait et à côté de ton nom.\n\nCe que tu obtiens :\n- Tous les décrets pour ta guilde : appels aux armes, rassemblements, décrets royaux, inspections de tabard.\n- L'Agenda de ta guilde.\n- Le salon du Département de l'Héraldique, et le salon Maître et Correspondants.\n\nTa guilde uniquement. L'armée entière, c'est l'affaire de la Couronne et du Haut Conseil.\n\nUne règle : ne crie pas au loup. Appelle quand ça compte.",
	RB_CORR_HERALDRY_TITLE = "Correspondant de l'Héraldique",
	RB_CORR_JUSTICE = "Salut,\n\nTu es maintenant le correspondant de la Justice de <%s>. Tu maintiens la paix.\n\nLe boulot : surveiller le chat de ta guilde, régler les problèmes, et travailler avec ton maître de guilde et le Conseil de justice.\n\nCe qui se voit : le bouclier du Conseil de justice sur ton portrait et à côté de ton nom.\n\nCe que tu obtiens :\n- Tout le bureau de La Garde (onglet La Garde) pour les membres de ta guilde en dessous de toi : avertissements, sourdines, la liste de surveillance, signalements.\n- Quand je confirme un dossier après le vote du Haut Conseil, c'est toi qui l'appliques dans ta guilde. L'addon n'expulse jamais personne tout seul.\n- Le salon du Conseil de justice.\n\nUne règle : sois juste. Mêmes règles pour tes amis.",
	RB_CORR_JUSTICE_TITLE = "Correspondant de la Justice",
	RB_CORR_TREASURY = "Salut,\n\nTu es maintenant le correspondant du Trésor de <%s>. Sympa.\n\nLe boulot : tenir en ordre les registres du Trésor et le partage de la banque de ta guilde, avec ton maître de guilde et le Trésor fédéral.\n\nCe qui se voit : le bouclier du Trésor fédéral sur ton portrait et à côté de ton nom.\n\nCe que tu obtiens :\n- La banque de ta guilde dans l'addon. Ouvre la banque de guilde avec l'addon activé et il en prend un instantané. Il ne déplace jamais rien. Ton maître de guilde décide si toute la guilde la voit.\n- Le salon du Trésor fédéral, et le salon Maître et Correspondants.\n\nUne règle : l'or de la guilde appartient à la guilde. Tiens des comptes propres.",
	RB_CORR_TREASURY_TITLE = "Correspondant du Trésor",
	RB_CORR_WAR = "Bon,\n\nTu es maintenant le correspondant de la Guerre de <%s>. C'est toi qui fais que les raids ont lieu.\n\nLe boulot : organiser les raids et les opérations JcJ de ta guilde, ses groupes de raid et ses comptes rendus d'après-action.\n\nCe qui se voit : le bouclier du Département de la Guerre sur ton portrait et à côté de ton nom.\n\nCe que tu obtiens :\n- Les droits d'officier dans la Salle de guerre de ta guilde (onglet Le Royaume) : opérations, groupes de raid, postes, comptes rendus d'après-action.\n- Le salon du Département de la Guerre, et le salon Maître et Correspondants.\n\nTout ça à l'intérieur de ta propre guilde.\n\nUne règle : tu planifies, tu appelles, tu te pointes.",
	RB_CORR_WAR_TITLE = "Correspondant de la Guerre",
	RB_COUNCIL = "Bon, écoute.\n\nTu fais maintenant partie du Haut Conseil. C'est énorme. Ce rang, ça ne se farme pas. Tu as été choisi. Ne nous le fais pas regretter.\n\nLe boulot : diriger Olympus avec moi. Juger, appeler l'armée, prendre soin de la maison.\n\nCe qui se voit : les ailes d'argent sur ton portrait, et le dragon d'argent devant ton nom dans le chat. Tu peux ajouter une icône après lui dans Mon profil, Icônes.\n\nCe que tu obtiens :\n- Décrets royaux, inspections de tabard, appels aux armes et rassemblements pour toute l'armée.\n- La Garde : les signalements du conseil, et un vote sur chaque Jugement. C'est moi qui ai le dernier mot.\n- Jusqu'à 10 modérateurs Olympus à toi.\n- Nommer des Apôtres, et ouvrir le classement public de l'Église.\n- Nommer des Légats pour la guilde du Roi, sur le Trône.\n- Le salon du Haut Conseil.\n\nUne règle : tu agis pour Olympus, pas pour ta guilde.",
	RB_COUNCIL_ARTISANRY = "Tu diriges l'Artisanat. Le salon de ton département réunit le correspondant de l'Artisanat de chaque guilde. Les outils propres au département arriveront plus tard.",
	RB_COUNCIL_BADGE = "Le bouclier de ton département s'affiche aussi sur ton portrait.",
	RB_COUNCIL_CHURCHDEPT = "Tu diriges le département de l'Église. Le salon de ton département réunit le correspondant de l'Église de chaque guilde, et le classement de l'onglet Église t'est ouvert.",
	RB_COUNCIL_HERALDRY = "Tu diriges l'Héraldique. Tu publies l'Agenda du Roi pour toute l'armée. Le salon de ton département réunit le correspondant de l'Héraldique de chaque guilde.",
	RB_COUNCIL_JUSTICE = "Tu sièges au Conseil de justice. C'est moi qui le préside. Quand je ne suis pas là, c'est un Haut Conseiller. Le salon de ton département réunit le correspondant de la Justice de chaque guilde.",
	RB_COUNCIL_TITLE = "Le Haut Conseil",
	RB_COUNCIL_TREASURY = "Tu diriges le Trésor fédéral. Le salon de ton département réunit le Trésorier fédéral et le correspondant du Trésor de chaque guilde.",
	RB_COUNCIL_WAR = "Tu diriges la Guerre. Dans la Salle de guerre de ta propre guilde, tu comptes comme officier. Le salon de ton département réunit le correspondant de la Guerre de chaque guilde.",
	RB_GM_ARTISANRY = "Correspondant de l'Association de l'Artisanat",
	RB_GM_ARTISANRY_JOB = "Met tes artisans en relation avec ceux qui en ont besoin.",
	RB_GM_ARTISANRY_SHOWS = "Le bouclier de l'Association de l'Artisanat sur son portrait et à côté de son nom.",
	RB_GM_ARTISANRY_UNLOCKS = "Un lien vers le tableau des Artisans, et le salon de l'Artisanat. Pas encore de pouvoir en plus.",
	RB_GM_BANK = "Banque de guilde",
	RB_GM_BANK_TEXT = "Ouvre ta banque de guilde une fois avec l'addon activé : il en prend un instantané, sans jamais rien déplacer. C'est toi qui décides si toute la guilde la voit.",
	RB_GM_BTN_CHURCH = "Ouvrir l'Église",
	RB_GM_BTN_LEGATE = "Nommer un Légat",
	RB_GM_BTN_NAME = "En nommer un",
	RB_GM_BTN_OPEN = "Ouvrir",
	RB_GM_BTN_WATCHER = "Nommer un Garde",
	RB_GM_BTN_WRITE = "La rédiger",
	RB_GM_CHARTER = "Charte de guilde",
	RB_GM_CHARTER_TEXT = "Objectif, langue, soirs de raid et les classes que tu cherches, publics pendant sept jours. Ça aide les recrues à vous choisir.",
	RB_GM_CHURCH = "Correspondant de l'Église (l'onglet Église)",
