	RB_GM_CHURCH_UNLOCKS = "Le salon de l'Église, les chiffres de l'onglet Église, et l'enregistrement des recrues qu'il a amenées.",
	RB_GM_CLOSE = "Une règle : ton pouvoir s'arrête à la porte de ta guilde. À l'intérieur, fais-en bon usage.\n\nMaintenant, va construire quelque chose. C'est parti !",
	RB_GM_DONE = "[x] %s",
	RB_GM_GET = "Ce que tu obtiens en tant que maître de guilde :\n- Les ailes de bronze sur ton portrait, et la marque de bronze à côté de ton nom.\n- L'onglet Guilde : cette liste, et la page de chaque département.\n- Appels aux armes, rassemblements, décrets royaux et inspections de tabard pour ta guilde.\n- L'Agenda de ta guilde, et des questions Vox Populi pour ta guilde.\n- La Garde pour ta guilde, avec tes Capitaines.\n- Les salons Maîtres de guilde, Maîtres et Légats, Maître et Légats, et Maître et Correspondants.",
	RB_GM_HERALDRY = "Correspondant du Département de l'Héraldique",
