	RB_GM_JUSTICE_UNLOCKS = "Tout le bureau de La Garde pour les membres de ta guilde en dessous de lui. Le salon du Conseil de justice.",
	RB_GM_LEGATES = "Légats (%d sur %d)",
	RB_GM_LEGATES_JOB = "Chacun mène un groupe de raid : lui-même et jusqu'à 39 camarades de guilde qui ont accepté, 40 en tout.",
	RB_GM_LEGATES_SHOWS = "Le bouclier de Légat sur son portrait, et le même bouclier à côté de son nom.",
	RB_GM_LEGATES_UNLOCKS = "Son groupe dans la Salle de guerre (onglet Le Royaume) : affecter et retirer des soldats, invitations de raid, un chat privé d'escouade. Les salons Maîtres et Légats.",
	RB_GM_MUST = "À nommer",
	RB_GM_OPEN = "Bon, écoute.\n\nTu diriges une guilde dans Olympus. Et c'est pas rien. Olympus, c'est l'armée, mais ta guilde, c'est là où les gens vivent vraiment.\n\nTu ne peux pas tout faire seul, et tu ne devrais pas. Nomme tes gens. Chaque ligne ci-dessous s'ouvre en un clic et se coche toute seule une fois faite. Un titre par personne, et uniquement des membres de ta propre guilde.",
	RB_GM_PREVIEW = "(Dans la lettre d'un maître de guilde, chaque ligne se coche toute seule, et son bouton ouvre l'étape.)",
	RB_GM_SHOWS = "Ce qui se voit : %s",
	RB_GM_TITLE = "Maître de guilde : nomme tes gens",
	RB_GM_TODO = "[  ] %s",
	RB_GM_TREASURY = "Correspondant du Trésor fédéral",
	RB_GM_TREASURY_JOB = "Tient en ordre les registres du Trésor de ta guilde et le partage de la banque, avec toi et le Trésor fédéral.",
	RB_GM_TREASURY_SHOWS = "Le bouclier du Trésor fédéral sur son portrait et à côté de son nom.",
	RB_GM_TREASURY_UNLOCKS = "Le stock de la banque de ta guilde et sa page dans le Trésor. Le salon du Trésor fédéral.",
	RB_GM_UNLOCKS = "Débloque : %s",
	RB_GM_WAR = "Correspondant du Département de la Guerre",
	RB_GM_WAR_JOB = "Gère les raids et les opérations JcJ de ta guilde.",
	RB_GM_WAR_SHOWS = "Le bouclier du Département de la Guerre sur son portrait et à côté de son nom.",
	RB_GM_WAR_UNLOCKS = "Les droits d'officier dans ta Salle de guerre : opérations, groupes de raid, postes, comptes rendus d'après-action. Le salon du Département de la Guerre.",
	RB_GM_WATCHERS = "Gardes",
	RB_GM_WATCHERS_TEXT = "Tes Capitaines ont déjà La Garde. Les Gardes l'ont aussi, pour tes membres en dessous d'eux.",
	RB_GM_WORTH = "À faire aussi",
	RB_GUILD_TAB_LINK = "Ta lettre du Roi : %d sur %d nommés",
	RB_HAND = "Bon,\n\nJe t'ai fait Main du Roi. Et c'est pas rien. Tu utilises mes outils, en mon nom.\n\nCe qui se voit : pas de nouveau cadre. L'onglet Trône s'ouvre pour toi.\n\nCe que tu obtiens :\n- Convoquer les Seigneurs : un appel de chaque Seigneur et Capitaine en ligne.\n- Inspection royale : l'armée vérifie les tabards autour d'elle.\n- L'Agenda du Roi, et les questions Vox Populi.\n- Les portes : là où vont les nouvelles recrues.\n- Appels aux armes et rassemblements pour toute l'armée.\n\nCe qui reste à moi : la liste des Mains, les brefs, les audiences et les grâces.\n\nUne règle : ne spamme pas l'armée. Chaque appel que tu envoies s'affiche sur l'écran de tout le monde.",
	RB_HAND_TITLE = "Main du Roi",
	RB_HELP = "  /oly duties - relire les lettres du Roi pour tes fonctions",
	RB_KEEPER = "Salut,\n\nJe t'ai nommé gardien du trésor. Je te confie l'or. Fais pas de trucs bizarres.\n\nLe boulot : garder une partie du trésor sur ton personnage, aux côtés du Trésorier.\n\nCe qui se voit : pas de nouveau cadre.\n\nCe que tu obtiens :\n- Ton propre registre dans l'onglet Trésor. L'or et les objets qu'on te donne par échange ou par courrier comptent comme des dons, tout seuls, une fois que tu as accepté de le partager.\n- L'or entre deux gardiens est un transfert, jamais un don.\n- Ce que tu gagnes en jouant reste à toi. Une vente ou un achat est inscrit comme non compté.\n\nIl y a cinq gardiens au maximum, et je peux te retirer le titre à tout moment.\n\nUne règle : l'or donné, ce n'est jamais à toi de le dépenser.",
	RB_KEEPER_TITLE = "Gardien du trésor",
	RB_LAUNCH = "Bon, écoutez.\n\nLa bêta est finie. On y est. Olympus est lancé.\n\nIl n'y a pas si longtemps, c'était quelques guildes et une idée. Et maintenant, regardez-moi ça. Une armée, un royaume, et chacun de vous dedans. C'est énorme. Sincèrement.\n\nPas grand-chose de nouveau cette fois. Chaque fonction a maintenant sa propre lettre, et les maîtres de guilde ont une liste à cocher dans la leur. C'est tout. Le reste, c'est à vous.\n\nEncore une chose. Fern nous a construit un hall de guilde : olympus.roachcouncil.com. Si vous êtes sur le Discord, connectez-vous et passez les portes. Merci, Fern. Vraiment.\n\nSoyez cool dans le chat. Aidez les nouveaux. Amenez vos amis.\n\nBon jeu. Je suis sérieux. C'est parti !",
	RB_LAUNCH_TITLE = "Les portes sont ouvertes",
	RB_LEGATE = "Bon, écoute.\n\nTu es maintenant Légat de <%s>. C'est parti !\n\nLe boulot : mener un groupe de raid. Toi et jusqu'à 39 camarades de guilde qui ont accepté, 40 en tout. Emmène-les aux événements, aux raids et aux guerres.\n\nCe qui se voit : le bouclier de Légat sur ton portrait, et le même bouclier à côté de ton nom.\n\nCe que tu obtiens :\n- Ton groupe dans la Salle de guerre (onglet Le Royaume) : affecter et retirer des soldats, inviter en raid ceux qui sont en ligne, un chat privé d'escouade.\n- Les salons Maîtres et Légats dans l'onglet Discussion.\n\nRien n'est automatique : aucune invitation, exclusion ou promotion dans la guilde. Les groupes sont facultatifs, et les gens peuvent jouer avec un autre meneur.\n\nUne règle : n'inscris que des gens qui ont dit oui.",
	RB_LEGATE_TITLE = "Légat",
	RB_LINK = "Lettres de fonction",
	RB_LINK_PREVIEW = "Lettres de fonction (aperçu)",
	RB_MISSIONARY = "Salut,\n\nTu es maintenant missionnaire de l'Église, dans le réseau de %s. Bienvenue.\n\nLe boulot : amener de nouveaux joueurs dans Olympus.\n\nCe qui se voit : les trois meilleurs missionnaires des 30 derniers jours portent la houlette du berger.\n\nCe que tu obtiens :\n- Invite de nouveaux joueurs dans ta guilde et l'addon le compte tout seul, une fois que l'addon d'un autre joueur l'a confirmé.\n- Tu as amené quelqu'un qu'un autre joueur a invité ? Enregistre-le dans l'onglet Église. Il compte s'il rejoint une guilde Olympus sous 14 jours.\n- Jusqu'à 12 missionnaires à toi, sauf si tu es déjà cinq niveaux plus bas.\n- L'onglet Église, le salon Apôtres et missionnaires, et le salon de l'Église.\n\nPoints : 10 pour chaque nouveau joueur, 5 de plus s'il reste 7 jours.\n\nUne règle : uniquement de vrais nouveaux joueurs. Les rerolls et les changements de guilde au sein d'Olympus ne comptent jamais.",
	RB_MISSIONARY_TITLE = "Missionnaire",
	RB_MODERATOR = "Bon, écoute.\n\nTu es maintenant modérateur Olympus. Tu gardes propres les chats de toute l'armée. C'est un vrai travail.\n\nLe boulot : gérer les abus, les insultes, le spam et les arnaques dans les chats d'Olympus.\n\nCe qui se voit : rien sur ton portrait.\n\nCe que tu obtiens :\n- La modération du chat de La Garde : supprimer des lignes et mettre des gens en sourdine partout dans Olympus, maîtres des autres guildes compris. Jamais le maître de <Olympus>, ni personne au-dessus de toi.\n- Le salon de La Garde, avec le Haut Conseil, les autres modérateurs et moi.\n\nTu le restes tant que celui qui t'a nommé te garde sur sa liste.\n\nUne règle : ce que tu vois dans l'équipe reste dans l'équipe.",
	RB_MODERATOR_TITLE = "Modérateur Olympus",
	RB_NONE = "Pas encore de lettre pour une fonction de ce personnage.",
	RB_NOT_LIVE = "Les lettres de fonction ne sont pas encore sorties.",
	RB_PAGE_NOTE = "Une lettre du Roi pour chaque fonction que ce personnage occupe, la première fois qu'il l'occupe. Elles restent ici, et dans Mon profil > Lettres, pour les relire.",
	RB_PAGE_TITLE = "Lettres de tes fonctions",
	RB_PREVIEW_DEPT = "%s : %s",
	RB_PREVIEW_HEAD = "Aperçu : toutes les lettres de fonction",
	RB_PREVIEW_LETTER = "Aperçu : rien n'est enregistré ni envoyé, et les boutons ne font rien.",
	RB_PREVIEW_NOTE = "Pour l'auteur et le Roi : chaque lettre telle que son titulaire la lit. Un aperçu n'enregistre rien, n'envoie rien et ne marque rien comme lu, et ses boutons ne font rien.",
	RB_PREVIEW_OFF = "Pas encore sorties : personne ne reçoit de lettre tant que l'auteur ne les a pas activées.",
	RB_READY = "Une lettre du Roi t'attend : %s. Ouvre-la avec /oly duties, ou dans Mon profil > Lettres.",
	RB_REALM_BACK = "< Retour au Royaume",
	RB_SITE_TITLE = "Les portes d'Olympus",
	RB_STEWARD = "Salut,\n\nTu es maintenant mon Intendant. Ça veut dire que quand je ne suis pas là, tu es moi. Pas de pression.\n\nLe boulot : faire tourner le Trône en mon nom.\n\nCe qui se voit : pas de nouveau cadre. Ton pouvoir est dans l'onglet Trône.\n\nCe que tu obtiens :\n- Le Trône, en agissant pour le Roi : l'appel, l'Inspection royale, l'Agenda, Vox Populi, les portes.\n- Des Mains à toi. Tu les nommes, tu leur retires le titre.\n- Les bascules et les gardiens du trésor, et le montant des cotisations hebdomadaires.\n- Tous les types de décret, pour toute l'armée.\n- Le salon du Secrétariat, avec moi.\n\nCe qui reste à moi : mes propres Mains, les audiences, les brefs et les grâces.\n\nUne règle : agis comme si je te regardais. Parce que ce sera le cas.",
	RB_STEWARD_TITLE = "Mon Intendant",
	RB_TREASURER = "Salut,\n\nTu es le Trésorier fédéral. Tu détiens l'or d'Olympus. Ouais. Tout.\n\nLe boulot : garder le trésor honnête, et dans un seul registre.\n\nCe qui se voit : le cadre de dragon du Trésorier sur ton portrait.\n\nCe que tu obtiens :\n- L'onglet Trésor et ton registre : chaque échange et chaque courrier avec de l'or ou des objets y entre tout seul, une fois que tu as accepté de le partager.\n- Les cotisations hebdomadaires, payées à toi. Qui a payé reste privé : le Roi et les Capitaines de chaque guilde le voient, jamais l'armée.\n- Le salon du Haut Conseil et le salon du Trésor fédéral.\n\nCe que tu gagnes en jouant est à toi. Ça n'entre jamais dans le registre.\n\nUne règle : chaque pièce de cuivre qui entre, chaque pièce de cuivre qui sort. Dans le registre.",
	RB_TREASURER_TITLE = "Le Trésorier fédéral",
	RB_WATCHER = "Salut,\n\nTon maître de guilde t'a nommé Garde de <%s>. Tu aides à tenir le chat propre.\n\nLe boulot : avoir l'oeil sur le chat de ta guilde, et intervenir quand quelqu'un dépasse les bornes.\n\nCe qui se voit : rien sur ton portrait.\n\nCe que tu obtiens : tout le bureau de La Garde (onglet La Garde) pour les membres de ta guilde en dessous de toi : avertissements, sourdines, la liste de surveillance, signalements et dossiers.\n\nTu restes Garde tant que ton maître de guilde te maintient sur sa liste.\n\nUne règle : avertis d'abord. Les sourdines montent ensuite : une heure, un jour, une semaine.",
	RB_WATCHER_TITLE = "Garde",
